using System;
using PieceOfCake.Core;
using UnityEngine;

namespace PieceOfCake.Game.Content
{
    /// <summary>
    /// Catalogue of every visual asset the game needs. Generated by
    /// <c>Tools ▸ Piece of Cake ▸ Rebuild Art Catalog</c> and editable in the Inspector.
    /// </summary>
    [CreateAssetMenu(menuName = "Piece of Cake/Game Art", fileName = "GameArt")]
    public sealed class GameArt : ScriptableObject
    {
        [Serializable]
        public struct CellLook
        {
            public CellType type;
            public Material material;
        }

        [Serializable]
        public struct CustomerLook
        {
            public string key;
            public GameObject prefab;
        }

        [Header("Cake")]
        public Mesh cellMesh;
        public CellLook[] cellMaterials = Array.Empty<CellLook>();
        public Mesh creamCapMesh;
        public Material creamCapMaterial;
        public Mesh strawberryMesh;
        public Material[] strawberryMaterials = Array.Empty<Material>();
        public Mesh orderSliceMesh;
        public Material[] orderSliceMaterials = Array.Empty<Material>();

        [Header("Actors and props")]
        public GameObject chefPrefab;
        public GameObject antPrefab;
        public GameObject tablePrefab;
        public GameObject candlePrefab;
        public GameObject forkPrefab;
        public GameObject signPrefab;
        public CustomerLook[] customers = Array.Empty<CustomerLook>();

        [Header("Stage")]
        [Tooltip("Lit material tinted per theme for terrain blocks.")]
        public Material terrainMaterial;
        [Tooltip("Lit material tinted per theme for the decoration on top of terrain.")]
        public Material terrainTopMaterial;
        [Tooltip("Lit material tinted per theme for far-away background cakes.")]
        public Material sceneryMaterial;
        [Tooltip("Unlit textured material used for the sky gradient.")]
        public Material skyMaterial;
        [Tooltip("Unlit transparent particle material.")]
        public Material particleMaterial;
        public ThemeStyle[] themes = Array.Empty<ThemeStyle>();

        public Material CellMaterial(CellType type)
        {
            foreach (var look in cellMaterials)
            {
                if (look.type == type) return look.material;
            }

            return cellMaterials.Length > 0 ? cellMaterials[0].material : null;
        }

        /// <summary>Prefab for a customer key; unknown keys fall back to the first entry.</summary>
        public GameObject CustomerPrefab(string key)
        {
            foreach (var look in customers)
            {
                if (string.Equals(look.key, key, StringComparison.OrdinalIgnoreCase)) return look.prefab;
            }

            return customers.Length > 0 ? customers[0].prefab : null;
        }

        /// <summary>Theme for a key; unknown keys fall back to the first theme.</summary>
        public ThemeStyle Theme(string key)
        {
            foreach (var theme in themes)
            {
                if (string.Equals(theme.key, key, StringComparison.OrdinalIgnoreCase)) return theme;
            }

            return themes.Length > 0 ? themes[0] : new ThemeStyle();
        }

        /// <summary>Names of required references that are missing (empty when the catalogue is complete).</summary>
        public string[] MissingReferences()
        {
            var missing = new System.Collections.Generic.List<string>();
            void Check(UnityEngine.Object o, string name)
            {
                if (o == null) missing.Add(name);
            }

            Check(cellMesh, nameof(cellMesh));
            Check(creamCapMesh, nameof(creamCapMesh));
            Check(creamCapMaterial, nameof(creamCapMaterial));
            Check(strawberryMesh, nameof(strawberryMesh));
            Check(orderSliceMesh, nameof(orderSliceMesh));
            Check(chefPrefab, nameof(chefPrefab));
            Check(antPrefab, nameof(antPrefab));
            Check(tablePrefab, nameof(tablePrefab));
            Check(candlePrefab, nameof(candlePrefab));
            Check(forkPrefab, nameof(forkPrefab));
            Check(signPrefab, nameof(signPrefab));
            Check(terrainMaterial, nameof(terrainMaterial));
            Check(terrainTopMaterial, nameof(terrainTopMaterial));
            Check(sceneryMaterial, nameof(sceneryMaterial));
            Check(skyMaterial, nameof(skyMaterial));
            Check(particleMaterial, nameof(particleMaterial));
            foreach (CellType type in Enum.GetValues(typeof(CellType)))
            {
                if (type != CellType.Order && CellMaterial(type) == null) missing.Add("cell material " + type);
            }

            if (customers.Length == 0) missing.Add(nameof(customers));
            if (themes.Length == 0) missing.Add(nameof(themes));
            return missing.ToArray();
        }
    }

    /// <summary>Colours and lighting of one stage theme.</summary>
    [Serializable]
    public sealed class ThemeStyle
    {
        public string key = "default";
        public Color skyTop = new Color(1f, 0.87f, 0.9f);
        public Color skyBottom = new Color(1f, 0.96f, 0.89f);
        public Color terrain = new Color(0.79f, 0.55f, 0.35f);
        public Color terrainTop = Color.white;
        public Color scenery = new Color(0.95f, 0.6f, 0.68f, 1f);
        public Color sunColor = Color.white;
        public float sunIntensity = 1.2f;
        public Color ambient = new Color(0.75f, 0.7f, 0.72f);
        [Tooltip("Dark themes (caves) get twinkling stars instead of background cakes.")]
        public bool starrySky;
    }
}
